 if(!(margin?isYearlyMarginPath(p):isYearlyCapitalPath(p))||!Number.isInteger(count))return false;
 const k=Math.max(1,Math.min(max,count)),values=[...(margin?p.nearTermMargins:p.yearlySalesCapital)],first=margin?1:2,current=values.length+first-1;
 if(k===current)return false;
 rememberEdit((margin?'marginPath':'capitalPath')+':years');
 // Years you drop are remembered, so shrinking and growing again restores them.
 const stash=yearlyStash.get(key()+kind)||[];
 for(let year=k+1;year<=current;year++)stash[year]=values[year-first];
 for(let year=current+1;year<=k;year++)values.push(stash[year]??glideValue(kind,year));
 yearlyStash.set(key()+kind,stash);
 values.length=k-first+1;
