  }
}

function scan() {
  if (!document.querySelector('.guided-screen')) return;
  finePrint();
  eyebrows();
  storyMap();
  nextCards();
  bridge();
}
onScan(scan);
// The four story numbers follow the sliders and fields as they move.
document.addEventListener('input', e => { if (e.target?.matches?.('#g-growth, #g-targetMargin, #g-salesCapital, #g-wacc')) storyMap(); }, true);

// ---------- phones: the header steps aside while you read down the page ----------
// Scrolling down hides it (transform only); any upward scroll brings it back.
{
  const phone = matchMedia('(max-width: 600px)');
  let lastY = scrollY, hidden = false, queued = false;
  const header = () => document.querySelector('body > aside');
  const apply = hide => { if (hide === hidden) return; hidden = hide; header()?.classList.toggle('rx-header-away', hide); document.documentElement.toggleAttribute('data-rx-header-away', hide); };
  addEventListener('scroll', () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => {
      queued = false;
      const y = scrollY, dy = y - lastY;
      if (!phone.matches || y < 140) { apply(false); lastY = y; return; }
      if (Math.abs(dy) < 8) return;
      // Keep it visible while a field inside it, or its menu, has focus.
      if (!header()?.contains(document.activeElement) && !document.querySelector('.appearance-disclosure[open]')) apply(dy > 0);
      lastY = y;
    });
  }, {passive: true});
  phone.addEventListener('change', () => apply(false));
}

dist/skins/report.css.beforeText:
/* Annual Report — after Swiss corporate annual reports: clean white stock,
   one grotesk family set large and tight, and the key figures printed on a
   solid cobalt panel. Signature: that panel wipes in once when the page loads.
   Everything else stays quiet: hairline frames, a sliding cobalt rule under the
   selected tab, no texture. Schibsted Grotesk throughout. */

@font-face { font-family: 'Report Grotesk'; font-style: normal; font-weight: 400 900; font-display: swap; src: url('./fonts/schibsted-grotesk-latin-wght-normal.woff2') format('woff2'); }
@font-face { font-family: 'Instrument Serif'; font-style: normal; font-weight: 400; font-display: swap; src: url('./fonts/schibsted-grotesk-latin-wght-normal.woff2') format('woff2'); }
@font-face { font-family: 'Instrument Serif'; font-style: italic; font-weight: 400; font-display: swap; src: url('./fonts/schibsted-grotesk-latin-wght-normal.woff2') format('woff2'); }
@font-face { font-family: 'DM Sans'; font-style: normal; font-weight: 100 1000; font-display: swap; src: url('./fonts/schibsted-grotesk-latin-wght-normal.woff2') format('woff2'); }

:root[data-skin="report"] {
  --font-ui: 'Report Grotesk', 'Helvetica Neue', Arial, sans-serif;
  --font-editorial: 'Report Grotesk', 'Helvetica Neue', Arial, sans-serif;
  --sk-display: 'Report Grotesk', 'Helvetica Neue', Arial, sans-serif;
  --sk-ui: 'Report Grotesk', 'Helvetica Neue', Arial, sans-serif;
  --sk-num: 'Report Grotesk', 'Helvetica Neue', Arial, sans-serif;
  --sk-num-weight: 650;
  --sk-num-tracking: -.035em;
  --sk-display-weight: 700;
  --sk-display-tracking: -.035em;
  --sk-h1: clamp(42px, 5vw, 70px);
  --sk-h2: 30px;
  --sk-eyebrow-size: 14px;
  --sk-eyebrow-tracking: .03em;
  --sk-eyebrow-weight: 600;
  --sk-r-sm: 4px;
  --sk-r-md: 6px;
  --sk-r-lg: 6px;
  --sk-r-btn: 4px;
  --sk-r-tab: 0;
  --sk-bar-radius: 0;
  --sk-thumb-radius: 50%;
}

/* Six editions of the report. Cobalt Ledger is the house default. */
:root[data-skin="report"]:is([data-theme="slate"], :not([data-theme])) {
