    width: 38px !important; height: 22px !important; min-width: 38px !important; min-height: 22px !important; padding: 0 !important; border: 0 !important; border-radius: 999px !important; vertical-align: middle;
    background: color-mix(in srgb, var(--ink) 18%, transparent); transition: background-color 200ms;
