/* ---------- phase timelines (capital efficiency, margin path) ---------- */
:root[data-skin="report"] {
  & body .rx-phases { position: relative; padding: 34px 2px 4px; margin: 0 0 22px; user-select: none; -webkit-user-select: none; }
  & body .rx-phases.is-invalid { opacity: .4; pointer-events: none; }
  & body .rx-ph-track { position: relative; height: 52px; touch-action: none; cursor: ew-resize; }
  & body .rx-ph-bands { position: absolute; inset: 0; border-radius: 12px; overflow: hidden; background: color-mix(in srgb, var(--ink) 5%, transparent); }
  & body .rx-ph-band {
    position: absolute; top: 0; bottom: 0; display: flex; flex-direction: column; justify-content: center; gap: 1px;
    padding: 0 12px; min-width: 0; overflow: hidden; white-space: nowrap; box-shadow: inset -1px 0 0 var(--surface);
    transition: left 280ms var(--rx-ease), width 280ms var(--rx-ease);
  }
  & body .rx-phases.is-dragging .rx-ph-band { transition-duration: 140ms; }
  & body .rx-ph-band b { font: 650 12.5px/1.2 var(--sk-ui); overflow: hidden; text-overflow: ellipsis; }
  & body .rx-ph-band span { font: 500 12px/1.2 var(--sk-ui); font-variant-numeric: tabular-nums; opacity: .85; overflow: hidden; text-overflow: ellipsis; }
  & body .rx-ph-band.is-narrow { padding: 0 6px; }
  & body .rx-ph-band.is-narrow :is(b, span) { font-size: 0; }
  & body .rx-ph-band.is-a { background: var(--accent); color: var(--on-accent, #fff); }
  & body .rx-ph-band.is-b { background: color-mix(in srgb, var(--accent) 42%, var(--surface)); color: var(--ink); }
  & body .rx-ph-band.is-fade { background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 30%, var(--surface)), color-mix(in srgb, var(--accent) 8%, var(--surface))); color: var(--ink); }
  & body .rx-ph-band.is-end { background: repeating-linear-gradient(135deg, transparent 0 6px, color-mix(in srgb, var(--ink) 6%, transparent) 6px 7px); color: var(--muted); }

  & body .rx-ph-handle {
    all: unset; box-sizing: border-box; position: absolute; top: -8px; bottom: -8px; width: 30px; margin-left: -15px; z-index: 2;
    cursor: ew-resize; display: flex; justify-content: center; transition: left 280ms var(--rx-ease);
  }
  & body .rx-phases.is-dragging .rx-ph-handle { transition-duration: 140ms; }
  & body .rx-ph-handle::before {
    content: ""; width: 4px; height: 100%; border-radius: 3px; background: var(--ink);
    box-shadow: 0 0 0 2px var(--surface), 0 2px 8px rgb(0 0 0 / .25); transition: transform 160ms var(--rx-ease);
  }
  & body .rx-ph-handle:hover::before, & body .rx-ph-handle:focus-visible::before { transform: scaleX(1.5); }
  & body .rx-ph-handle:focus-visible { outline: none; }
  & body .rx-ph-tag {
    position: absolute; bottom: calc(100% + 4px); left: 50%; transform: translateX(-50%);
    padding: 3px 8px; border-radius: 999px; background: var(--ink); color: var(--surface);
    font: 650 11.5px/1.3 var(--sk-ui); font-variant-numeric: tabular-nums; white-space: nowrap;
    transition: transform 160ms var(--rx-ease), background-color 160ms;
  }
  & body .rx-phases.has-raised { padding-top: 60px; transition: padding-top 200ms var(--rx-ease); }
  & body .rx-ph-handle.is-raised .rx-ph-tag { bottom: calc(100% + 30px); }
  & body .rx-ph-handle.is-raised::after { content: ""; position: absolute; bottom: calc(100% + 4px); left: 50%; width: 1px; height: 26px; background: var(--ink); opacity: .35; }
  & body .rx-ph-handle:is(:hover, :focus-visible) .rx-ph-tag { background: var(--accent); color: var(--on-accent, #fff); transform: translateX(-50%) translateY(-2px); }
  & body .rx-ph-axis { position: relative; height: 22px; margin-top: 8px; }
  & body .rx-ph-axis i { position: absolute; top: 0; width: 1px; height: 5px; background: color-mix(in srgb, var(--ink) 22%, transparent); }
  & body .rx-ph-axis i[data-y]::after { content: "Y" attr(data-y); position: absolute; top: 7px; left: 50%; transform: translateX(-50%); font: 500 11px/1 var(--sk-ui); color: var(--muted); white-space: nowrap; }
  & body .rx-ph-hint { margin: 2px 0 0 !important; font-size: 12.5px !important; color: var(--muted); }

  /* The exact-number fields: three even columns, label above value. */
  & body .capital-phase-controls.capital-phase-controls .operating-timing-controls { padding: 22px 24px 24px !important; }
  & body .capital-phase-controls.capital-phase-controls .operating-timing-inputs {
    display: grid !important; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px 28px !important; align-items: end;
  }
  & body .capital-phase-controls.capital-phase-controls .operating-timing-inputs > div { display: flex !important; flex-direction: column; align-items: stretch; gap: 8px; min-width: 0; }
  & body .capital-phase-controls.capital-phase-controls .operating-timing-inputs label { font: 500 13px/1.35 var(--sk-ui) !important; color: var(--muted) !important; }
  & body .capital-phase-controls.capital-phase-controls .operating-timing-inputs input { width: 100% !important; max-width: none !important; text-align: left !important; font-size: 26px !important; }
  & body .margin-phase-controls .rx-phases { margin-top: 18px; }
  @media (max-width: 600px) {
    & body .capital-phase-controls.capital-phase-controls .operating-timing-controls { padding: 18px 16px 20px !important; }
    & body .capital-phase-controls.capital-phase-controls .operating-timing-inputs { gap: 14px 14px !important; }
    & body .rx-ph-band { padding: 0 8px; }
    & body .rx-ph-band :is(b, span) { font-size: 11px; }
  }
}

/* ---------- language swipe ---------- */
:root[data-skin="report"][data-locale-swipe]::view-transition { pointer-events: none; }
:root[data-skin="report"][data-locale-swipe]::view-transition-group(root) { animation: none; }
:root[data-skin="report"][data-locale-swipe]::view-transition-image-pair(root) { isolation: isolate; }
:root[data-skin="report"][data-locale-swipe]::view-transition-old(root),
:root[data-skin="report"][data-locale-swipe]::view-transition-new(root) { animation: none; mix-blend-mode: normal; }
/* The outgoing language is pushed right and wiped from the left. */
:root[data-skin="report"][data-locale-swipe]::view-transition-old(root) {
  z-index: 2; animation: rx-locale-out 680ms cubic-bezier(.65, 0, .35, 1) both;
}
/* The incoming language slides in a little behind the edge. */
:root[data-skin="report"][data-locale-swipe]::view-transition-new(root) {
  z-index: 1; animation: rx-locale-in 680ms cubic-bezier(.16, 1, .3, 1) both;
}
:root[data-skin="report"][data-locale-swipe] *,
:root[data-skin="report"][data-locale-swipe] *::before,
:root[data-skin="report"][data-locale-swipe] *::after { transition: none !important; }
@keyframes rx-locale-out {
  from { clip-path: inset(0 0 0 0); transform: none; }
  to { clip-path: inset(0 0 0 100%); transform: translateX(48px); }
}
@keyframes rx-locale-in {
  from { transform: translateX(-36px); opacity: .25; }
  60% { opacity: 1; }
  to { transform: none; opacity: 1; }
}
:root[data-skin="report"] body .rx-swipe-edge {
  position: fixed; inset: 0 auto 0 -160px; width: 160px; z-index: 2147483000; pointer-events: none;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent) 14%, transparent) 70%, color-mix(in srgb, var(--accent) 55%, transparent) 97%, var(--accent));
  will-change: transform;
}

/* ---------- Guided header: one set of edges, even rhythm ---------- */
:root[data-skin="report"] {
  /* The summary and the view tabs share the toolbar's left and right edges. */
  & body .guided-screen .workspace-summary { padding-inline: 0 !important; column-gap: 40px !important; row-gap: 6px !important; padding-block: 20px 8px !important; }
  & body .guided-screen .workspace-view-tabs { padding-inline: 0 !important; margin-top: 28px !important; }
  /* Toolbar: every column is label (19px) + 3px + a 36px control, so labels
     share one top line and controls share one bottom line. */
  & body .guided-screen .workspace-toolbar { align-items: flex-end !important; column-gap: 20px !important; }
  & body .guided-screen .toolbar-model { padding: 0 !important; }
  & body .guided-screen .toolbar-model > span { display: block; line-height: 19px !important; margin: 0 0 3px !important; }
  & body .guided-screen .toolbar-model > b { display: block; line-height: 18px !important; }
  & body .guided-screen .toolbar-model > small { display: block; line-height: 16px !important; margin: 2px 0 0 !important; }
  & body .guided-screen .workspace-toolbar-actions { align-items: stretch; gap: 8px !important; }
  & body .guided-screen .workspace-toolbar-actions > button { min-height: 40px; }
  /* Source line: the filing link follows the date instead of floating mid-row. */
  & body .guided-screen .valuation-source-context, & body .guided-screen .result-context { justify-content: flex-start !important; gap: 6px 18px !important; flex-wrap: wrap; }
  & body .guided-screen :is(.valuation-source-context, .result-context) > a { margin-left: 0 !important; }
  & body .guided-screen :is(.valuation-source-context, .result-context) > span { flex: 0 1 auto !important; }
  & body .guided-screen .approved-company-name { margin-bottom: 4px; }
  /* Phone: tab rows stay one line and scroll sideways (with an edge fade). */
  @media (max-width: 600px) {
    & body :is(.workspace-view-tabs, .assumption-tabs, .annual-context-tabs) {
      flex-wrap: nowrap !important; overflow-x: auto; scrollbar-width: none; overscroll-behavior-x: contain;
    }
    & body :is(.workspace-view-tabs, .assumption-tabs, .annual-context-tabs)::-webkit-scrollbar { display: none; }
    & body :is(.workspace-view-tabs, .assumption-tabs, .annual-context-tabs) > button { flex: none !important; white-space: nowrap; }
  }
  /* Under the value panel: the disclosure row and its note breathe. */
  & body .guided-screen #guided-results .approved-summary-details { margin-top: 14px !important; }
  & body .guided-screen #guided-results .approved-summary-details > summary { padding-block: 6px; }
  & body .guided-screen #guided-results .approved-summary-details :is(p, small, .micro) { text-align: left !important; line-height: 1.6; }
  & body .guided-screen #guided-results .live-value { margin: 0 !important; }
}

/* New presentation-only motion also stops when reduced motion changes mid-flow. */
@media (prefers-reduced-motion: reduce) {
  :root[data-skin="report"] .sk-route-enter,
  :root[data-skin="report"][data-locale-swipe]::view-transition-old(root),
  :root[data-skin="report"][data-locale-swipe]::view-transition-new(root) { animation: none !important; }
}

