/* ---------- set each year: the editor's base layout ---------- */
:root[data-skin="report"] {
  & body .guided-screen .workspace-editor .yearly-path{margin:14px 0 0;padding:0;border:0;min-width:0}
  & body .guided-screen .workspace-editor .yearly-path legend{font-size:12px!important;font-weight:550;margin:0 0 10px}
  & body .guided-screen .workspace-editor .yearly-path-head{display:grid;grid-template-columns:repeat(2,minmax(0,max-content));gap:14px 32px;align-items:end;margin:0 0 16px}
