  & body .guided-screen .workspace-editor .yearly-path-stepper{display:inline-flex;align-items:stretch;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:var(--surface)}
  & body .guided-screen .workspace-editor .yearly-path-stepper button{min-width:40px;min-height:40px;padding:0;border:0;border-radius:0;background:transparent;font-size:18px;line-height:1;color:var(--ink);cursor:pointer}
  & body .guided-screen .workspace-editor .yearly-path-stepper button:disabled{color:var(--control);cursor:default}
  & body .guided-screen .workspace-editor .yearly-path-stepper input{width:48px;min-width:0;height:40px;min-height:40px;padding:0;border:0;border-inline:1px solid var(--line);border-radius:0;text-align:center;font-size:16px!important;font-weight:600;background:transparent}
  & body .guided-screen .workspace-editor .yearly-path-terminal input{width:72px;min-height:40px;height:40px;padding:0 9px;border:1px solid var(--line);font-size:16px!important}
  & body .guided-screen .workspace-editor .yearly-path-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(78px,1fr));gap:12px 10px}
  & body .guided-screen .workspace-editor .yearly-path-cell{min-width:0;display:flex;flex-direction:column}
  & body .guided-screen .workspace-editor .yearly-path-cell label{font-size:11px!important;color:var(--muted);margin:0 0 6px}
  & body .guided-screen .workspace-editor .yearly-path-cell input{width:100%;min-width:0;min-height:38px;height:38px;padding:0 9px;text-align:right;border:1px solid var(--line);font-size:16px!important;font-weight:500;background:var(--surface)}
  & body .guided-screen .workspace-editor .yearly-path-cell small{font-size:10.5px;line-height:1.35;color:var(--muted);margin-top:5px}
}

/* ---------- path charts: one bar per year, both ends spelled out ---------- */
:root[data-skin="report"] {
  & body .rx-path { margin: 22px 0 6px; user-select: none; -webkit-user-select: none; }
  & body .rx-path.is-invalid { opacity: .4; pointer-events: none; }

  /* Where the path starts and where it settles, the same in both tabs. */
  & body .rx-path-ends { display: grid; grid-template-columns: minmax(0, 1fr) 40px minmax(0, 1fr); align-items: stretch; margin-bottom: 26px; }
  & body .rx-path-end {
    position: relative; display: flex; flex-direction: column; gap: 3px; min-width: 0;
    padding: 14px 16px 15px; border-radius: 14px; background: color-mix(in srgb, var(--ink) 4%, transparent);
    transition: background-color 180ms, box-shadow 220ms var(--rx-ease), transform 220ms var(--rx-ease);
  }
  & body .rx-pe-k { font: 600 11.5px/1.2 var(--sk-ui); letter-spacing: .02em; color: var(--muted); }
  & body .rx-path-end b { font: var(--sk-num-weight, 650) 28px/1.1 var(--sk-num); letter-spacing: var(--sk-num-tracking, -.03em); font-variant-numeric: tabular-nums; color: var(--ink); margin-top: 2px; }
  & body .rx-path-end small { font: 500 12px/1.4 var(--sk-ui); color: var(--muted); }
  & body .rx-path-end.is-slider { cursor: pointer; background: color-mix(in srgb, var(--accent) 7%, var(--surface)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 22%, transparent); }
  & body .rx-path-end.is-slider b { color: var(--accent); }
  & body .rx-path-end.is-slider:hover { transform: translateY(-1px); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent), 0 6px 18px -10px color-mix(in srgb, var(--accent) 60%, transparent); }
  & body .rx-path-end.is-slider:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  /* A settle value set on another step links there; quieter than the slider tag. */
  & body .rx-path-end.is-link { cursor: pointer; }
  & body .rx-path-end.is-link:hover { background: color-mix(in srgb, var(--ink) 7%, transparent); }
  & body .rx-path-end.is-link:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  & body .rx-path-end.is-link .rx-pe-tag { background: transparent; color: var(--accent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 40%, transparent); transition: background-color 160ms, color 160ms; }
  & body .rx-path-end.is-link:hover .rx-pe-tag { background: var(--accent); color: var(--on-accent, #fff); }
  & body .rx-pe-tag {
    position: absolute; top: 12px; right: 12px; padding: 2px 8px; border-radius: 999px;
    background: var(--accent); color: var(--on-accent, #fff); font: 600 10.5px/1.5 var(--sk-ui); font-style: normal; letter-spacing: .01em;
  }
  & body .rx-path-arrow { position: relative; align-self: center; height: 1px; margin: 0 8px; background: color-mix(in srgb, var(--ink) 28%, transparent); }
  & body .rx-path-arrow::after { content: ""; position: absolute; right: -1px; top: -3.5px; width: 7px; height: 7px; border: solid color-mix(in srgb, var(--ink) 40%, transparent); border-width: 1.5px 1.5px 0 0; transform: rotate(45deg); }

  /* The bars. Heights and positions move by transform only. */
  & body .rx-path-plot { position: relative; height: 172px; margin: 0 0 30px; touch-action: pan-y; contain: layout style; }
  & body .rx-path:has(+ .rx-phases) .rx-path-plot { margin-bottom: 4px; }
  & body .rx-path:has(+ .rx-phases) .rx-pp-yr { display: none; }
  & body .rx-path:has(+ .rx-phases) .rx-path-hint { display: none; }
  & body .rx-pp-cols { position: absolute; inset: 0; }
  & body .rx-pp-col { position: absolute; top: 0; bottom: 0; cursor: pointer; }
  & body .rx-pp-col::before { content: ""; position: absolute; inset: -6px 2px -4px; border-radius: 8px; background: color-mix(in srgb, var(--ink) 5%, transparent); opacity: 0; transition: opacity 160ms; }
  & body .rx-pp-col:hover::before { opacity: 1; }
  & body .rx-pp-col.is-set { cursor: ns-resize; }
  & body .rx-pp-col[data-act]::after {
    content: "+ " attr(data-act); position: absolute; left: 50%; bottom: 8px; transform: translate(-50%, 4px); opacity: 0;
    padding: 2px 7px; border-radius: 999px; background: var(--ink); color: var(--surface); font: 600 10.5px/1.5 var(--sk-ui); white-space: nowrap; pointer-events: none;
    transition: opacity 160ms, transform 200ms var(--rx-ease); z-index: 3;
  }
  & body .rx-pp-col[data-act]:hover::after { opacity: 1; transform: translate(-50%, 0); }
  & body .rx-pp-bar {
    position: absolute; top: 0; left: 18%; right: 18%; height: 100%; transform-origin: 50% 0; border-radius: 2px;
    background: color-mix(in srgb, var(--accent) 34%, var(--surface));
    transition: transform 300ms var(--rx-ease), background-color 220ms;
  }
  & body .rx-pp-col[data-tone="set"] .rx-pp-bar { background: var(--accent); }
  & body .rx-pp-col[data-tone="end"] .rx-pp-bar { background: color-mix(in srgb, var(--ink) 13%, var(--surface)); }
  & body .rx-pp-head { position: absolute; inset: 0; pointer-events: none; transition: transform 300ms var(--rx-ease); }
  & body .rx-path.is-dragging :is(.rx-pp-bar, .rx-pp-head, .rx-pp-mature) { transition-duration: 70ms; }
  & body .rx-pp-knob {
    all: unset; box-sizing: border-box; position: absolute; top: 0; left: 50%; width: 18px; height: 18px; margin: -9px 0 0 -9px;
    border-radius: 50%; background: var(--surface); box-shadow: 0 0 0 2.5px var(--accent) inset, 0 2px 6px rgb(0 0 0 / .18);
    pointer-events: auto; cursor: ns-resize; touch-action: none; transition: transform 180ms var(--rx-ease), box-shadow 180ms;
  }
  /* A fingertip-sized grab area around each knob on touch screens. */
  & body .rx-pp-knob::before { content: ""; position: absolute; inset: -6px; border-radius: 50%; }
  @media (pointer: coarse) { & body .rx-pp-knob::before { inset: -13px; } }
  & body .rx-pp-col:hover .rx-pp-knob, & body .rx-pp-knob:focus-visible { transform: scale(1.18); }
  & body .rx-pp-knob:focus-visible { box-shadow: 0 0 0 2.5px var(--accent) inset, 0 0 0 4px color-mix(in srgb, var(--accent) 25%, transparent), 0 2px 6px rgb(0 0 0 / .18); }
  & body .rx-path.is-dragging .rx-pp-knob:focus { transform: scale(1.3); background: var(--accent); }
  & body .rx-pp-val {
    position: absolute; top: 0; left: 50%; transform: translate(-50%, calc(-100% - 6px)); padding: 1px 5px; border-radius: 6px;
    font: 600 11.5px/1.35 var(--sk-ui); font-variant-numeric: tabular-nums; white-space: nowrap; color: var(--muted);
    opacity: 0; transition: opacity 160ms, color 160ms, background-color 160ms;
  }
  & body .rx-pp-col.is-set .rx-pp-val { transform: translate(-50%, calc(-100% - 13px)); color: var(--ink); opacity: 1; }
  & body .rx-path.is-narrow .rx-pp-col.is-set .rx-pp-val { opacity: 0; }
  & body .rx-pp-col:hover .rx-pp-val, & body .rx-path .rx-pp-col:has(.rx-pp-knob:focus) .rx-pp-val { opacity: 1 !important; z-index: 4; }
  & body .rx-pp-col:has(.rx-pp-knob:focus) .rx-pp-val { background: var(--accent); color: var(--on-accent, #fff); }
  & body .rx-pp-yr { position: absolute; left: 50%; bottom: -22px; transform: translateX(-50%); font: 500 11px/1 var(--sk-ui); color: var(--muted); white-space: nowrap; }
  & body .rx-pp-mature { position: absolute; inset: 0; pointer-events: none; transition: transform 300ms var(--rx-ease); z-index: 2; }
  & body .rx-pp-mature::before { content: ""; position: absolute; top: 0; left: -4px; right: -4px; border-top: 1.5px dashed color-mix(in srgb, var(--ink) 42%, transparent); }
  & body .rx-pp-mature span {
    position: absolute; top: 0; right: 0; transform: translateY(calc(-100% - 3px)); padding: 0 0 0 6px;
    font: 600 11px/1.3 var(--sk-ui); font-variant-numeric: tabular-nums; color: var(--muted); background: var(--surface); border-radius: 4px;
  }
  & body .rx-path-hint { margin: 0 !important; font-size: 12.5px !important; color: var(--muted); }
  /* Growth draws its path with the same chart as margin and capital. */
  & body .rx-path[data-kind="growth"] + .approved-growth-path { display: none !important; }
  & body .rx-path[data-kind="growth"] { margin-top: 26px; }
  & body fieldset.yearly-path > .rx-phases { margin-top: 0; }

  /* Exact entry under the drawing: figures on a rule, like the other studio numbers. */
  & body .guided-screen .workspace-editor .yearly-path { margin-top: 18px; }
  & body .guided-screen .workspace-editor .yearly-path-head { gap: 18px 40px; margin: 6px 0 22px; }
  & body .guided-screen .workspace-editor .yearly-path-stepper { border-radius: 999px; border-color: color-mix(in srgb, var(--ink) 14%, transparent); }
  & body .guided-screen .workspace-editor .yearly-path-stepper button { min-width: 42px; transition: background-color 140ms, color 140ms; }
  & body .guided-screen .workspace-editor .yearly-path-stepper button:not(:disabled):hover { background: color-mix(in srgb, var(--accent) 9%, transparent); color: var(--accent); }
  & body .guided-screen .workspace-editor .yearly-path-stepper input { border: 0 !important; width: 44px; font: 650 18px/1 var(--sk-num) !important; font-variant-numeric: tabular-nums; }
  & body .guided-screen .workspace-editor :is(.yearly-path-grid, .yearly-path-terminal) input {
    border: 0 !important; border-bottom: 2px solid var(--rx-rule) !important; border-radius: 0 !important; background: transparent !important;
    padding: 4px 2px !important; height: auto !important; min-height: 0 !important; text-align: left !important;
    font: 650 22px/1.15 var(--sk-num) !important; letter-spacing: -.03em; font-variant-numeric: tabular-nums; color: var(--ink);
    transition: border-color 140ms, color 140ms, background-color 140ms;
  }
  & body .guided-screen .workspace-editor :is(.yearly-path-grid, .yearly-path-terminal) input:hover { border-bottom-color: var(--accent) !important; color: var(--accent); }
  & body .guided-screen .workspace-editor :is(.yearly-path-grid, .yearly-path-terminal) input:focus { border-bottom-color: var(--accent) !important; color: var(--accent); background: color-mix(in srgb, var(--accent) 7%, transparent) !important; }
  & body .guided-screen .workspace-editor :is(.yearly-path-grid, .yearly-path-terminal) input[aria-invalid="true"] { border-bottom-color: var(--error) !important; color: var(--error); }
  & body .guided-screen .workspace-editor .yearly-path-terminal input { width: 76px; }
  & body .guided-screen .workspace-editor .yearly-path-grid { grid-template-columns: repeat(auto-fill, minmax(84px, 1fr)); gap: 18px 18px; }
  & body .guided-screen .workspace-editor .yearly-path-cell.is-linked input { color: var(--accent); }
  & body .guided-screen .workspace-editor .yearly-path-cell.is-linked small { font-size: 11px; }
  & body .guided-screen .workspace-editor .yearly-path-cell:has(input:focus) label { color: var(--accent); }

  @media (max-width: 600px) {
    & body .rx-path-ends { grid-template-columns: minmax(0, 1fr) 22px minmax(0, 1fr); margin-bottom: 22px; }
    & body .rx-path-arrow { margin: 0 4px; }
    & body .rx-path-end { padding: 12px 12px 13px; border-radius: 12px; }
    & body .rx-path-end b { font-size: 22px; }
    & body .rx-path-end small { font-size: 11.5px; }
    & body .rx-pe-tag { top: 9px; right: 9px; padding: 1px 6px; font-size: 10px; }
    & body .rx-path-plot { height: 148px; }
    & body .guided-screen .workspace-editor .yearly-path-head { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 14px 16px; }
    & body .guided-screen .workspace-editor .yearly-path-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px 12px; }
    & body .guided-screen .workspace-editor :is(.yearly-path-grid, .yearly-path-terminal) input { font-size: 20px !important; }
  }
}

/* ---------- Learn: one column on the page grid ---------- */
:root[data-skin="report"] {
  /* The quiz, the examples and the checks share one measure and one left edge. */
  & body #learn :is(.learn-random-quiz, .learn-original-examples, .learn-worked-example, #quizzes ~ .panel) {
    margin-left: 0 !important; margin-right: auto !important; max-width: 880px !important; width: 100% !important; box-sizing: border-box;
  }
  & body #learn :is(.learn-original-examples, .learn-worked-example, #quizzes ~ .panel) { margin-top: 28px !important; }
}

/* ---------- Sources: the snapshot file field is a drop zone ---------- */
:root[data-skin="report"] {
  & body #data input[type="file"] {
    display: block; width: 100%; box-sizing: border-box; margin: 6px 0 18px; padding: 22px 18px;
    border: 1.5px dashed color-mix(in srgb, var(--ink) 22%, transparent); border-radius: 12px;
    background: color-mix(in srgb, var(--accent) 3%, var(--surface)); color: var(--muted);
    font: 500 13.5px/1.4 var(--sk-ui); cursor: pointer; transition: border-color 160ms, background-color 160ms;
  }
  & body #data input[type="file"]:hover, & body #data input[type="file"]:focus-visible {
    border-color: var(--accent); background: color-mix(in srgb, var(--accent) 7%, var(--surface)); outline: none;
  }
  & body #data input[type="file"]::file-selector-button {
    margin-right: 14px; padding: 9px 16px; border: 0; border-radius: 999px; cursor: pointer;
    background: var(--ink); color: var(--surface); font: 600 13px/1.2 var(--sk-ui); transition: background-color 160ms;
  }
  & body #data input[type="file"]:hover::file-selector-button { background: var(--accent); color: var(--on-accent, #fff); }
}

/* ---------- Year-by-year: the growth bars pick the year you edit ---------- */
:root[data-skin="report"] {
  & body .annual-revenue-growth-bars .approved-growth-column { cursor: pointer; position: relative; border-radius: 8px; transition: background-color 160ms; }
  & body .annual-revenue-growth-bars .approved-growth-column:hover { background: color-mix(in srgb, var(--ink) 5%, transparent); }
  & body .annual-revenue-growth-bars .approved-growth-column:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  & body .annual-revenue-growth-bars .approved-growth-column.is-editing { background: color-mix(in srgb, var(--accent) 9%, transparent); }
  & body .annual-revenue-growth-bars .approved-growth-column.is-editing .approved-growth-year { color: var(--accent); font-weight: 700; }
  & body .annual-revenue-growth-bars .approved-growth-column.is-editing .approved-growth-year::after {
    content: ""; display: block; width: 18px; height: 2px; margin: 4px auto 0; border-radius: 2px; background: var(--accent);
  }
}

/* ---------- phones: the Guided editor sits on the page gutter ---------- */
:root[data-skin="report"] {
  @media (max-width: 600px) {
    /* The framed card has no room for inner padding here; drop the frame so
       text never touches a border, and keep a hairline between sections. */
    & body .guided-screen .workspace-editor { border: 0 !important; border-radius: 0 !important; box-shadow: none !important; background: transparent !important; }
    & body .guided-screen .workspace-editor > :is(.save-status, .editor-save, footer):last-child { padding-inline: 0 !important; }
    & body .guided-screen .workspace-editor :is(.driver-number, .driver-number input:not(:focus)) { background: transparent !important; }
    & body .rx-path[data-kind="growth"] { margin-top: 8px; }
  }
}
:root[data-skin="report"] {
  /* Axis labels are right-aligned to the plot; on phones they may reach into the gutter. */
  & body svg.annual-path-chart { overflow: visible; }
}

/* ---------- wide screens: one centred measure for every page ---------- */
:root[data-skin="report"] {
  /* Past ~1560px the gutter grows instead of the content, so the header,
     the toolbar and every page keep a readable, centred measure. */
  --sk-gutter: max(clamp(18px, 3vw, 40px), calc((100vw - 1480px) / 2));
}

/* ---------- Guided header: the result reads as one card ---------- */
:root[data-skin="report"] {
  @media (min-width: 761px) {
    & body .guided-screen .workspace-summary { grid-template-columns: minmax(0, 1fr) minmax(400px, 540px) !important; align-items: start !important; }
    & body .guided-screen #guided-results {
      text-align: left !important; align-self: start;
      /* The disclosures under the figures sit on a pale tray of the panel colour. */
      background: color-mix(in srgb, var(--sk-panel) 8%, var(--surface)); border-radius: 4px; overflow: hidden;
      box-shadow: 0 0 0 1px color-mix(in srgb, var(--sk-panel) 16%, transparent);
    }
    & body .guided-screen #guided-results .live-value { justify-content: space-between !important; align-items: flex-end !important; gap: 24px !important; padding: 20px 24px 22px !important; border-radius: 4px 4px 0 0; }
    & body .guided-screen #guided-results .live-value > div:first-child { text-align: left !important; min-width: 0; }
    & body .guided-screen #guided-results .live-value .valuation-number { font-size: clamp(40px, 3.3vw, 52px) !important; line-height: 1 !important; margin: 8px 0 0 !important; letter-spacing: -.05em !important; white-space: nowrap; }
    & body .guided-screen #guided-results .live-value .valuation-number > span { display: inline-flex !important; flex-direction: column; vertical-align: baseline; margin-left: 8px !important; line-height: 1.15; font-size: 13px !important; letter-spacing: 0 !important; }
    & body .guided-screen #guided-results .live-value .valuation-number small { margin: 0 !important; font-size: 12px !important; }
    & body .guided-screen #guided-results .live-value-meta { text-align: right !important; padding: 0 0 2px 20px !important; min-width: 0 !important; }
    & body .guided-screen #guided-results .live-value-meta b { font-size: 24px !important; line-height: 1.2; letter-spacing: -.03em; margin: 2px 0; }
    & body .guided-screen #guided-results > :not(.live-value) { margin: 0 !important; padding-inline: 24px !important; text-align: left !important; }
    & body .guided-screen #guided-results > .approved-summary-details > summary { min-height: 40px; padding-block: 8px !important; font-size: 12.5px !important; }
    & body .guided-screen #guided-results > :not(.live-value) + :not(.live-value) { border-top: 1px solid color-mix(in srgb, var(--sk-panel) 14%, transparent); }
    & body .guided-screen #guided-results > :last-child:not(.live-value) { padding-bottom: 4px !important; }
    & body .guided-screen #guided-results > .valuation-timing-note { padding-block: 10px !important; font-size: 12px !important; line-height: 1.5; color: var(--muted); }
    & body .guided-screen #guided-results > .valuation-timing-note > span { display: inline !important; }
    /* The company block and the card share a top edge; the view tabs follow at one rhythm. */
    & body .guided-screen .workspace-summary { padding-block: 24px 0 !important; }
    & body .guided-screen .workspace-view-tabs { margin: 36px 0 20px !important; }
  }
}

/* ---------- Guided journey: story → four value drivers → equity ---------- */
:root[data-skin="report"] {
  /* Step tabs carry their journey number; Sources and Details sit apart as reference. */
  & body .guided-screen .assumption-tabs { flex-wrap: nowrap !important; overflow-x: auto; scrollbar-width: none; overscroll-behavior-x: contain; }
  & body .guided-screen .assumption-tabs::-webkit-scrollbar { display: none; }
  & body .guided-screen .assumption-tabs > button { flex: none !important; white-space: nowrap; display: inline-flex !important; align-items: center; gap: 7px; }
  & body .guided-screen .assumption-tabs > button:is([data-step="1"], [data-step="2"], [data-step="3"], [data-step="4"], [data-step="5"], [data-step="6"])::before {
    content: attr(data-step); display: inline-grid; place-items: center; width: 18px; height: 18px; border-radius: 50%;
    font: 600 10.5px/1 var(--sk-ui); font-variant-numeric: tabular-nums;
    color: var(--muted); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ink) 22%, transparent);
    transition: background-color 160ms, color 160ms, box-shadow 160ms;
  }
  & body .guided-screen .assumption-tabs > button[aria-selected="true"]::before { background: var(--accent); color: var(--on-accent, #fff); box-shadow: none; }
  & body .guided-screen .assumption-tabs > button[data-step="0"] { margin-left: 10px !important; position: relative; }
  & body .guided-screen .assumption-tabs > button[data-step="0"]::after {
    content: ""; position: absolute; left: -6px; top: 50%; width: 1px; height: 16px; translate: 0 -50%; background: var(--line);
  }
  & body .guided-screen .assumption-tabs > button:is([data-step="0"], [data-step="7"]):not([aria-selected="true"]) { color: color-mix(in srgb, var(--muted) 88%, transparent) !important; }

  /* Every step opens with the same eyebrow, so the headings on both sides line up. */
  & body .guided-screen .editor-intro > .eyebrow:not(.rx-journey-eyebrow) { display: none !important; }
  & body .guided-screen .editor-intro > .rx-journey-eyebrow { display: block; margin: 0 0 10px !important; color: var(--accent) !important; }

  /* Profitability: the bar path above already shows the margin through the forecast. */
  & body .guided-screen #editor-group-3 .margin-path-visual { display: none !important; }

  /* ---- next step ---- */
  & body .rx-next { display: grid; gap: 10px; margin: 32px 0 6px; padding-top: 24px; border-top: 1px solid var(--line); }
  & body .rx-next-go {
    display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "kicker arrow" "title arrow"; align-items: center; gap: 4px 18px;
    width: 100%; min-height: 0 !important; padding: 18px 22px !important; text-align: left; cursor: pointer;
    background: color-mix(in srgb, var(--accent) 6%, var(--surface)) !important; color: var(--ink) !important;
    border: 1px solid color-mix(in srgb, var(--accent) 22%, transparent) !important; border-radius: 12px !important;
    transition: background-color 180ms, border-color 180ms, transform 180ms cubic-bezier(.2, .8, .2, 1);
  }
  & body .rx-next-go:hover { background: color-mix(in srgb, var(--accent) 11%, var(--surface)) !important; border-color: color-mix(in srgb, var(--accent) 45%, transparent) !important; }
  & body .rx-next-go:active { transform: scale(.99); }
  & body .rx-next-kicker { grid-area: kicker; font: 600 11px/1.3 var(--sk-ui); letter-spacing: .06em; text-transform: uppercase; color: var(--accent); }
  & body .rx-next-title { grid-area: title; font: 600 19px/1.3 var(--sk-ui); letter-spacing: -.015em; color: var(--ink); }
  & body .rx-next-arrow {
    grid-area: arrow; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%;
    background: var(--accent); color: var(--on-accent, #fff); font-size: 18px; transition: transform 200ms cubic-bezier(.2, .8, .2, 1);
  }
  & body .rx-next-go:hover .rx-next-arrow { transform: translateX(3px); }
  & body .rx-next-back {
    justify-self: start; min-height: 32px !important; padding: 4px 0 !important; border: 0 !important; background: none !important;
    color: var(--muted) !important; font: 500 13px/1.3 var(--sk-ui); cursor: pointer;
  }
  & body .rx-next-back:hover { color: var(--ink) !important; }
  & body .rx-next-done {
    padding: 22px 24px; border-radius: 12px; color: var(--sk-panel-ink, #fff);
    background: radial-gradient(130% 150% at 0% 0%, color-mix(in srgb, var(--sk-panel) 88%, #fff) 0%, var(--sk-panel) 55%);
  }
  & body .rx-next-done > b { display: block; font: 600 20px/1.3 var(--sk-ui); letter-spacing: -.015em; color: inherit; }
  & body .rx-next-done > p { margin: 6px 0 16px !important; max-width: 52ch; font-size: 13.5px !important; line-height: 1.55; color: inherit !important; opacity: .86; }
  & body .rx-next-actions { display: flex; flex-wrap: wrap; gap: 10px; }
  & body .rx-next-actions > button { min-height: 40px !important; padding: 9px 18px !important; border-radius: 999px !important; font: 600 13.5px/1.2 var(--sk-ui); cursor: pointer; transition: background-color 160ms, transform 160ms; }
  & body .rx-next-primary { background: var(--sk-panel-ink, #fff) !important; color: var(--sk-panel) !important; border: 0 !important; }
  & body .rx-next-secondary { background: transparent !important; color: var(--sk-panel-ink, #fff) !important; border: 1px solid color-mix(in srgb, var(--sk-panel-ink, #fff) 45%, transparent) !important; }
  & body .rx-next-secondary:hover { background: color-mix(in srgb, var(--sk-panel-ink, #fff) 12%, transparent) !important; }
  & body .rx-next-actions > button:active { transform: scale(.97); }

  /* ---- Story: the four numbers ---- */
  & body .rx-story-map { margin: 22px 0 18px; padding: 20px; border-radius: 14px; background: color-mix(in srgb, var(--accent) 5%, var(--surface)); border: 1px solid color-mix(in srgb, var(--accent) 16%, transparent); }
  & body .rx-story-title { margin: 0 !important; font: 600 16px/1.3 var(--sk-ui) !important; letter-spacing: -.01em; color: var(--ink); }
  & body .rx-story-lead { margin: 4px 0 16px !important; font-size: 13px !important; line-height: 1.55; color: var(--muted); max-width: 60ch; }
  & body .rx-story-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
  & body .rx-story-cell {
    position: relative; display: grid !important; grid-template-rows: auto auto 1fr; align-content: start; gap: 2px; min-height: 0 !important;
    padding: 14px 14px 12px !important; text-align: left; cursor: pointer; border-radius: 10px !important;
    background: var(--surface) !important; color: var(--ink) !important; border: 1px solid var(--line) !important;
    transition: border-color 160ms, transform 180ms cubic-bezier(.2, .8, .2, 1), box-shadow 180ms;
  }
  & body .rx-story-cell:hover { border-color: color-mix(in srgb, var(--accent) 50%, transparent) !important; box-shadow: 0 6px 18px -12px color-mix(in srgb, var(--accent) 60%, transparent); transform: translateY(-1px); }
  & body .rx-story-cell:not(:last-child)::after {
    content: "→"; position: absolute; right: -9px; top: 50%; translate: 0 -50%; z-index: 1; width: 8px; text-align: center;
    font-size: 11px; color: color-mix(in srgb, var(--accent) 60%, transparent);
  }
  & body .rx-story-n { position: absolute; top: 12px; right: 12px; font: 600 10.5px/1 var(--sk-ui); color: var(--muted); }
  & body .rx-story-label { font: 600 12px/1.3 var(--sk-ui); color: var(--muted); padding-right: 14px; }
  & body .rx-story-value { font: 600 26px/1.15 var(--sk-ui) !important; letter-spacing: -.035em; color: var(--accent) !important; margin-top: 4px; }
  & body .rx-story-sub { font-size: 11.5px !important; line-height: 1.35; color: var(--muted); }
  @media (max-width: 1180px) { & body .rx-story-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } & body .rx-story-cell::after { display: none; } }

  /* ---- Forecast: how the value adds up ---- */
  & body .rx-bridge { margin: 4px 0 40px; padding-bottom: 32px; border-bottom: 1px solid var(--line); }
  & body .rx-bridge-head h3 { margin: 0 !important; font: 600 24px/1.25 var(--sk-ui) !important; letter-spacing: -.025em; color: var(--ink); }
  & body .rx-bridge-head p { margin: 6px 0 22px !important; font-size: 13.5px !important; color: var(--muted); max-width: 64ch; }
  & body .rx-bridge-plot { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 18px; height: 180px; padding-bottom: 1px; border-bottom: 1px solid color-mix(in srgb, var(--ink) 30%, transparent); }
  & body .rx-bridge-track { position: relative; height: 100%; }
  & body .rx-bridge-bar {
    position: absolute; inset: 0; transform-origin: 50% 100%; border-radius: 3px 3px 0 0;
    transform: translateY(calc(var(--b, 0) * -100%)) scaleY(var(--h, 0));
    transition: transform 520ms cubic-bezier(.2, .8, .2, 1), background-color 200ms;
    background: color-mix(in srgb, var(--accent) 40%, var(--surface));
  }
