/* ---------- Safari: hard colour stops never sit at a negative position ---------- */
:root[data-skin="report"] {
  /* WebKit paints a hard stop placed before 0 across the whole track, so a zero
     line at the left edge turned every history and profit bar dark. Clamp at 0. */
  & body .approved-history-track { background: linear-gradient(to right, var(--soft) max(0px, calc(var(--history-zero, 0%) - .5px)), var(--muted) max(0px, calc(var(--history-zero, 0%) - .5px)), var(--muted) max(0px, calc(var(--history-zero, 0%) + .5px)), var(--soft) max(0px, calc(var(--history-zero, 0%) + .5px))); }
  & body .approved-profit-track { background: linear-gradient(to right, var(--soft) max(0px, calc(var(--profit-zero, 0%) - .5px)), var(--muted) max(0px, calc(var(--profit-zero, 0%) - .5px)), var(--muted) max(0px, calc(var(--profit-zero, 0%) + .5px)), var(--soft) max(0px, calc(var(--profit-zero, 0%) + .5px))); }
  & body .approved-growth-track { background: linear-gradient(to top, transparent max(0px, calc(var(--growth-zero) - .5px)), var(--line) max(0px, calc(var(--growth-zero) - .5px)), var(--line) max(0px, calc(var(--growth-zero) + .5px)), transparent max(0px, calc(var(--growth-zero) + .5px))); }
}
